                if (m.getName().equals("getParsedOptionValue")) {
                    Class<?>[] pts = m.getParameterTypes();
                    if (pts.length == 2 && pts[0] == String.class) {
                        target = m;
                        break;
                    }
                }
            }
        }
        if (target == null) {
            throw new NoSuchMethodException("getParsedOptionValue(String, ..) not found");
        }
        target.setAccessible(true);
        Object ret = target.invoke(cmd, optionName, defaultSupplier);
        return (T) ret;
    }

