    @Test
    public void testPrivateResolveOptionInvokedViaReflection() throws Exception {
        TestCommandLine cmd = new TestCommandLine();
        Option opt = new Option("x", "xray", false, "desc");
        addOptionToCommandLine(cmd, opt);
        // Invoke private resolveOption(String) via reflection and verify it returns the expected Option
        Method resolveMethod = CommandLine.class.getDeclaredMethod("resolveOption", String.class);
        resolveMethod.setAccessible(true);
        Object returned = resolveMethod.invoke(cmd, "--xray");
        assertSame(opt, returned, "Private resolveOption should find the option by long name");
        // Also verify short name resolution
        returned = resolveMethod.invoke(cmd, "-x");
        assertSame(opt, returned, "Private resolveOption should find the option by short name");
        // And a non-existing option returns null
        returned = resolveMethod.invoke(cmd, "--doesnotexist");
        assertNull(returned, "Private resolveOption should return null when no matching option exists");
    }
